SELECT (COUNT(DISTINCT ?month) AS ?num_months)
WHERE {
  GRAPH <hydroturtle/quadica> {
    ?sensor a sosa:Sensor ;
            schema:name ?sensorName .
    FILTER(lcase(str(?sensorName)) = lcase("BW_CKS022"))
    ?obs sosa:madeBySensor ?sensor ;
         sosa:observedProperty hyobs:FlowNormalizedConcentrationSampleCount ;
         hyobs:hasAnalyte chebi:17632 ;
         sosa:resultTime ?date ;
         sosa:hasResult ?value .
    ?value qudt:numericValue ?num .
    FILTER(xsd:decimal(?num) > 10.5)
    FILTER(year(xsd:dateTime(?date)) = 1997)
    BIND(CONCAT(STR(year(xsd:dateTime(?date))), "-", LPAD(STR(month(xsd:dateTime(?date))),2,"0")) AS ?month)
